			sPicDesc: "",
			sAlbumName: albumName,
			sAlbumID: albumId,
			iAlbumTypeID: 0,
			iBitmap: 0,
			iUploadType: 0,
			iUpPicType: 0,
			iBatchID: timestamp,
			sPicPath: "",
			iPicWidth: 0,
			iPicHight: 0,
			iWaterType: 0,
			iDistinctUse: 0,
			iNeedFeeds: 1,
			iUploadTime: timestamp,
